(()=>{
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
const bank=[
// Original low-stakes placement tasks: receptive and controlled productive skills.
['Первые фразы','oi','Что означает Oi!?',['Привет!','Спасибо!','До завтра!'],0,'Oi — дружеское приветствие.'],
['Знакомство','nome','Как сказать «Я Ана»?',['Eu sou Ana.','Eu estou Ana.','Eu tenho Ana.'],0,'Для имени используем sou: Eu sou Ana.'],
['Понимание сообщения','oi','Друг пишет: «Bom dia! Tudo bem?» Что он делает?',['Прощается до завтра','Здоровается и спрашивает, как дела','Называет свой адрес'],1,'Bom dia — доброе утро; Tudo bem? — как дела?'],
['Короткий ответ','oi','Напиши по-португальски «Привет».',null,['oi','ola'],'Oi! или Olá!'],
['Состояние и место','estar','Как сказать «Я сейчас дома»?',['Eu sou em casa.','Eu estou em casa.','Eu tenho casa agora.'],1,'Для местонахождения человека: estou em casa.'],
['Просьба','cafe','В кафе ты хочешь заказать воду. Выбери вежливую просьбу.',['Eu fui à água.','Água é ontem.','Uma água, por favor.'],2,'Por favor смягчает просьбу.'],
['Чтение объявления','horas','«A farmácia abre às nove e fecha às dezoito.» Когда открывается аптека?',['В 9:00','В 18:00','В полдень'],0,'Abre — открывается; às nove — в девять.'],
['Настоящее время','rotina','Вставь одно слово: Eu ___ português todos os dias. (изучаю)',null,['estudo'],'Eu estudo português todos os dias.'],
['События в прошлом','ontem','«Ontem fui ao mercado, mas não comprei nada.» Что произошло?',['Покупки запланированы на завтра','Вчера человек сходил на рынок, но ничего не купил','Человек каждый день покупает продукты'],1,'Fui и comprei описывают завершённые события; não ... nada — ничего.'],
['Сравнение','comparar','Выбери «Этот автобус дешевле, чем такси».',['Este ônibus é mais barato que o táxi.','Este ônibus é muito barato ontem.','Este ônibus é tão que táxi.'],0,'Mais barato que — дешевле, чем.'],
['Время и привычки','imperfeito','«Quando era criança, eu brincava na rua.» Речь идёт…',['об одном событии завтра','о привычке в детстве','о приказе играть'],1,'Era и brincava задают фон и привычку в прошлом.'],
['Прошедшее: свой ответ','ontem','Вставь форму ir: Ontem eu ___ ao mercado. (Вчера я сходил на рынок.)',null,['fui'],'Ontem eu fui ao mercado.'],
['Аргумент и оговорка','conectores','«Embora o curso seja curto, ele é útil.» Какая мысль передана?',['Курс полезен, несмотря на то что короткий','Курс полезен только из-за цены','Курс ещё не начался'],0,'Embora вводит уступку: хотя / несмотря на то что.'],
['Просьба с условием','condicional','Как вежливо попросить повторить?',['Você repetiu ontem?','Você poderia repetir, por favor?','Você repete nunca.'],1,'Poderia — мог бы: вежливая просьба.'],
['Понимание позиции','opiniao','«O transporte melhorou, porém ainda faltam ônibus à noite.» Что думает автор?',['Проблем больше нет','Ночных автобусов слишком много','Есть улучшение, но ночных автобусов не хватает'],2,'Porém — однако; ainda faltam — всё ещё не хватает.'],
['Будущая ситуация','subjuntivo','Вставь форму ter: Se eu ___ tempo amanhã, vou estudar. (Если завтра у меня будет время.)',null,['tiver'],'После se о возможном будущем: se eu tiver tempo.']
].map((v,i)=>({id:'pt-'+i,band:Math.floor(i/4),skill:v[0],lesson:v[1],q:v[2],options:v[3],answer:v[4],why:v[5]}));
const labels=['С нуля · до A1','Основы A1','Бытовое общение A2','Более связная речь · ориентир B1'];
function begin(){return {version:2,course:'pt',at:new Date().toISOString(),answers:[],done:false}}
function current(s){return !s||s.done?null:bank[s.answers.length]}
function submit(s,value){if(s.done)return s;const q=current(s);if(!q)return s;const correct=q.options?Number(value)===q.answer:q.answer.some(a=>norm(a)===norm(value));s.answers.push({id:q.id,band:q.band,skill:q.skill,lesson:q.lesson,answer:String(value).slice(0,250),correct});const count=s.answers.length;if(count%4===0){const passed=s.answers.slice(-4).filter(a=>a.correct).length>=3&&s.answers.at(-1).correct;s.done=!passed||count===bank.length}return s}
function result(s){if(!s.done)throw Error('Placement incomplete');let mastered=-1;for(let b=0;b<4;b++){const a=s.answers.filter(a=>a.band===b);if(a.length===4&&a.filter(x=>x.correct).length>=3&&a.at(-1).correct)mastered=b;else break}const tested=Math.floor((s.answers.length-1)/4),weak=s.answers.filter(a=>!a.correct),start=['oi','estar','ontem','conectores'][Math.min(mastered+1,3)];const lesson=weak.find(a=>a.band===Math.min(mastered+1,3))?.lesson||start;return {version:2,course:'pt',at:new Date().toISOString(),level:mastered<0?'Pre-A1':['A1: первые фразы','A1','A2','B1: верхняя граница проверки'][mastered],mastered,ceiling:mastered===3,lesson,results:s.answers,summary:mastered<0?'Начнём с первых слов и коротких разговоров.':`Уверенно получились задания: ${labels[mastered]}. Следующий шаг — ${labels[Math.min(mastered+1,3)]}.`,testedBand:tested}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function page(u){const s=u.placementDraft,q=current(s);if(!s||s.done)return `<div class="narrow panel"><div class="eyebrow">Бразильский португальский · точка старта</div><h1>Найдём комфортную сложность</h1><p>От 4 до 16 заданий: слова, бытовые сообщения, грамматика и короткие ответы без вариантов. Примерно 5–10 минут.</p><p>Начинаем с простого. Три верных ответа из четырёх, включая короткий ответ без вариантов, открывают следующую ступень. Ошибка — подсказка для маршрута, а не плохая оценка. Можно выбрать «Пока не знаю».</p><p class="small">Задания составлены для Bora с ориентацией на описания навыков CEFR. Проверка не стандартизирована: она не оценивает произношение, свободную речь или готовность к Celpe-Bras. Не пользуйся переводчиком; разбор увидишь в конце.</p>${u.diagnosis?`<div class="notice">Последний ориентир: ${esc(u.diagnosis.summary)}</div><a href="#result">Посмотреть результат</a>`:''}<button class="btn" id="placement-begin">Начать проверку →</button></div>`;
return `<div class="narrow panel"><div class="eyebrow">Задание ${s.answers.length+1} из максимум 16 · ${esc(q.skill)}</div><progress value="${s.answers.length}" max="16" aria-label="Пройдено заданий"></progress><h1>${esc(q.q)}</h1>${q.options?`<div class="options">${q.options.map((o,i)=>`<button class="option" data-placement-answer="${i}">${esc(o)}</button>`).join('')}</div>`:`<form id="placement-write"><label>Твой ответ<input name="answer" maxlength="250" autocomplete="off" required></label><button class="btn">Ответить →</button></form>`}<button class="btn alt" id="placement-unknown">Пока не знаю</button><p class="small">Ответы сохраняются в аккаунте. Если уйдёшь со страницы, продолжим с этого места.</p><a href="#home">Продолжить позже</a></div>`}
function resultPage(u){const d=u.diagnosis;if(d?.version!==2)return `<div class="narrow panel"><h1>Обновим точку старта</h1><p>Теперь проверка подробнее и учитывает короткие письменные ответы.</p><a class="btn" href="#diagnosis">Пройти новую проверку</a></div>`;const lesson=window.BoraCourses[0].lessons.find(l=>l.id===d.lesson);return `<div class="narrow panel"><div class="eyebrow">Твой предварительный маршрут</div><h1>${esc(d.level)}</h1><p>${esc(d.summary)}</p><div class="notice">Начни с «${esc(lesson?.title||'Начать разговор')}». Ранее пройденные уроки сохраняются. Можно открыть любой урок или повторить основы.</div><a class="btn yellow" href="#courses/pt/${esc(d.lesson)}">Начать рекомендованный урок →</a><p class="small">Это ориентир для письменных заданий, не сертификат CEFR. ${d.ceiling?'Ты достиг верхней границы этой проверки; более высокий уровень здесь не измеряется.':''} Говорение, аудирование и свободное письмо требуют отдельной оценки.</p><h2>Что получилось и что повторить</h2>${d.results.map(r=>{const q=bank.find(q=>q.id===r.id);return `<details><summary>${r.correct?'✓':'↻'} ${esc(r.skill)}</summary><p>${esc(q.q)}</p><p>Твой ответ: ${esc(r.answer==='-1'?'Пока не знаю':q.options?.[Number(r.answer)]||r.answer)}</p><p>${esc(q.why)}</p>${!r.correct?`<a href="#courses/pt/${esc(r.lesson)}">Потренировать тему →</a>`:''}</details>`}).join('')}<p><a href="#courses/pt">Посмотреть всю программу</a> · <a href="#diagnosis">Повторить проверку</a></p><p class="small">Основа подхода: <a href="https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions" target="_blank" rel="noopener">описания навыков CEFR</a>. Задания и пороги Bora не являются официальным тестом.</p></div>`}
function bind(u,save,render){const $=s=>document.querySelector(s);if($('#placement-begin'))$('#placement-begin').onclick=()=>{u.placementDraft=begin();save();render()};const answer=v=>{if(!u.placementDraft||u.placementDraft.done)return;submit(u.placementDraft,v);if(u.placementDraft.done){if(u.diagnosis)u.diagnosisHistory=[...(u.diagnosisHistory||[]),u.diagnosis].slice(-10);u.diagnosis=result(u.placementDraft);u.program='pt';save();location.hash='result'}else{save();render();window.scrollTo(0,0)}};document.querySelectorAll('[data-placement-answer]').forEach(b=>b.onclick=()=>answer(b.dataset.placementAnswer));if($('#placement-unknown'))$('#placement-unknown').onclick=()=>answer('-1');if($('#placement-write'))$('#placement-write').onsubmit=e=>{e.preventDefault();answer(new FormData(e.target).get('answer'))}}
window.BoraPlacement={begin,current,submit,result,page,resultPage,bind,bank,norm};
})();
